/* 오늘 보낼 표현을 고른다.
 * 앱의 복습 기록은 브라우저 안에만 있어 여기서 읽을 수 없다.
 * 대신 날짜를 씨앗으로 삼아 전체 목록을 순서대로 회전시킨다 —
 * 매일 다른 묶음이 오고, 한 바퀴 돌면 다시 처음으로 온다. */
const bundle = $input.first().json;
const items = bundle.items || [];
if (!items.length) throw new Error('expressions.json 을 읽지 못했다');

const COUNT = 12;
const epochDay = Math.floor(Date.now() / 86400000);
const start = (epochDay * COUNT) % items.length;

const pick = [];
for (let i = 0; i < COUNT; i++) pick.push(items[(start + i) % items.length]);

const dateLabel = new Date().toLocaleDateString('ko-KR', {
  timeZone: 'Asia/Seoul', month: 'long', day: 'numeric', weekday: 'short'
});

const text = '[오늘의 영어 ' + dateLabel + ']\n\n' +
  pick.map((it, i) =>
    (i + 1) + '. ' + it.en + '\n   ' + it.ko + (it.note ? '\n   · ' + it.note : '')
  ).join('\n\n') +
  '\n\n— 전체 ' + bundle.count + '개 중 ' + COUNT + '개';

const html =
  '<div style="font-family:-apple-system,\'Apple SD Gothic Neo\',sans-serif;max-width:600px">' +
  '<h2 style="margin:0 0 4px">오늘의 영어</h2>' +
  '<p style="color:#888;margin:0 0 20px;font-size:14px">' + dateLabel + '</p>' +
  pick.map((it) =>
    '<div style="border-left:3px solid #e0a05a;padding:2px 0 2px 14px;margin-bottom:18px">' +
    '<div style="font-size:17px;font-weight:600">' + it.en + '</div>' +
    '<div style="color:#555;font-size:14px;margin-top:3px">' + it.ko + '</div>' +
    (it.note ? '<div style="color:#999;font-size:12px;margin-top:5px">' + it.note + '</div>' : '') +
    '<div style="color:#bbb;font-size:11px;margin-top:5px">' + it.modeTitle + ' · ' + it.scene + '</div>' +
    '</div>'
  ).join('') +
  '<p style="color:#aaa;font-size:12px">소리 내어 세 번씩 읽고, 앱에서 롤플레이로 확인하자.</p>' +
  '</div>';

/* 카카오 텍스트 템플릿은 200자 제한이 있다. 세 개만 짧게 보내고 나머지는 앱에서. */
const short = ('오늘의 영어 ' + dateLabel + '\n\n' +
  pick.slice(0, 3).map((it) => '· ' + it.en + ' — ' + it.ko).join('\n')).slice(0, 185);

return [{ json: { text, html, short, dateLabel, count: COUNT } }];
